    from capstone import CS_ARCH_X86, CS_MODE_32, CS_MODE_64, CS_OP_MEM, CS_OP_IMM, CS_OP_REG
except ImportError:
    print("[!] pip install capstone", file=sys.stderr); sys.exit(2)

KEYWORDS = [
    b'vip', b'VIP', b'premium', b'Premium', b'PRO', b'Pro version', b'licensed',
    b'license', b'License', b'activation', b'activate', b'registered', b'register',
    b'trial', b'Trial', b'subscription', b'subscribe', b'upgrade', b'unlock',
    b'member', b'Member', b'expire', b'expired', b'grace',
    '会员'.encode('utf-8'), '授权'.encode('utf-8'), '注册码'.encode('utf-8'),
    '激活'.encode('utf-8'), '试用'.encode('utf-8'), '高级版'.encode('utf-8'),
    '专业版'.encode('utf-8'), '已购买'.encode('utf-8'),
]

# short-jump condition opcodes -> (name, unconditional_form)
JCC8 = {
    0x70:'jo', 0x71:'jno', 0x72:'jb', 0x73:'jae', 0x74:'je', 0x75:'jne',
    0x76:'jbe', 0x77:'ja', 0x78:'js', 0x79:'jns', 0x7a:'jp', 0x7b:'jnp',
    0x7c:'jl', 0x7d:'jge', 0x7e:'jle', 0x7f:'jg',
}
JCC32 = {
    0x80:'jo', 0x81:'jno', 0x82:'jb', 0x83:'jae', 0x84:'je', 0x85:'jne',
    0x86:'jbe', 0x87:'ja', 0x88:'js', 0x89:'jns', 0x8a:'jp', 0x8b:'jnp',
    0x8c:'jl', 0x8d:'jge', 0x8e:'jle', 0x8f:'jg',
}

class PE:
    def __init__(self, path):
        self.path = path
        with open(path, 'rb') as f:
            self.data = bytearray(f.read())
        self.pe = pefile.PE(data=bytes(self.data), fast_load=True)
        self.base = self.pe.OPTIONAL_HEADER.ImageBase
        self.bits = 64 if self.pe.FILE_HEADER.Machine == 0x8664 else 32
        self.secs = []
        for s in self.pe.sections:
            self.secs.append(dict(
                name=s.Name.rstrip(b'\x00').decode('latin1', 'replace'),
                va=s.VirtualAddress, vsize=s.Misc_VirtualSize,
                raw=s.PointerToRawData, rawsize=s.SizeOfRawData,
                chars=s.Characteristics))
        self.entry = self.pe.OPTIONAL_HEADER.AddressOfEntryPoint

    def va2off(self, va):
        rva = va - self.base
        for s in self.secs:
            span = max(s['vsize'], s['rawsize'])
            if s['va'] <= rva < s['va'] + span:
                off = s['raw'] + (rva - s['va'])
                return off if 0 <= off < len(self.data) else None
        return None

    def off2va(self, off):
        for s in self.secs:
            if s['raw'] <= off < s['raw'] + s['rawsize']:
                return self.base + s['va'] + (off - s['raw'])
        return None

    def sec_bytes(self, name):
        for s in self.secs:
            if s['name'] == name:
                return s, bytes(self.data[s['raw']:s['raw'] + s['rawsize']])
        return None, b''

    def exec_sections(self):
        out = []
        for s in self.secs:
            if s['chars'] & 0x20000000:  # IMAGE_SCN_MEM_EXECUTE
                out.append((s, bytes(self.data[s['raw']:s['raw'] + s['rawsize']])))
        return out


def find_strings(pe):
    """returns list of (va, text) for ASCII and UTF-16LE keyword hits"""
    hits = []
    for s in pe.secs:
        blob = bytes(pe.data[s['raw']:s['raw'] + s['rawsize']])
        low = s['raw']
        for kw in KEYWORDS:
            for m in re.finditer(re.escape(kw), blob):
                va = pe.off2va(low + m.start())
                if va is None:
                    continue
                # widen to printable run
                a = m.start()
                while a > 0 and 32 <= blob[a-1] < 127:
                    a -= 1
                b = m.start() + len(kw)
                while b < len(blob) and 32 <= blob[b] < 127:
                    b += 1
                hits.append((va, blob[a:b].decode('latin1', 'replace')))
        # UTF-16LE
        for kw in KEYWORDS:
            u = kw.decode('latin1', 'replace')
            needle = u.encode('utf-16-le')
            for m in re.finditer(re.escape(needle), blob):
                va = pe.off2va(low + m.start())
                if va is not None:
                    hits.append((va, '[utf16] ' + u))
    # dedup by va
    seen, out = set(), []
    for va, t in hits:
        if va in seen:
            continue
        seen.add(va); out.append((va, t))
    return sorted(out)


def disasm(pe, va, length, count=None):
    md = capstone.Cs(CS_ARCH_X86, CS_MODE_64 if pe.bits == 64 else CS_MODE_32)
    md.detail = True
    off = pe.va2off(va)
    if off is None:
        return []
    code = bytes(pe.data[off:off + length])
    res, n = [], 0
    for i in md.disasm(code, va):
        res.append(i)
        n += 1
        if count and n >= count:
            break
    return res


def xrefs_to(pe, targets, max_hits=4000):
    """find code sites referencing any VA in targets"""
    tset = set(targets)
    found = []
    for s, blob in pe.exec_sections():
        base_va = pe.base + s['va']
        md = capstone.Cs(CS_ARCH_X86, CS_MODE_64 if pe.bits == 64 else CS_MODE_32)
        md.detail = True
        for insn in md.disasm(blob, base_va):
            hit = None
            for op in insn.operands:
                if op.type == CS_OP_MEM:
                    if pe.bits == 64 and op.mem.base == XC.X86_REG_RIP:
                        t = insn.address + insn.size + op.mem.disp
                        if t in tset:
                            hit = t; break
                    elif op.mem.disp in tset and op.mem.base == 0:
                        hit = op.mem.disp; break
                elif op.type == CS_OP_IMM and op.imm in tset:
                    hit = op.imm; break
            if hit is not None:
                found.append((insn.address, hit, insn))
                if len(found) >= max_hits:
                    return found
    return found


def classify_site(pe, va, window=64):
    """
    Given a code VA, disassemble forward and describe the first
    conditional-jump decision. Returns dict with patch suggestion.
    """
    insns = disasm(pe, va, 400, count=window)
    if not insns:
        return None
    # find first jcc whose preceding 1-3 insns contain test/cmp/call
    for idx, insn in enumerate(insns):
        b = insn.bytes
        kind = None
        if len(b) >= 2 and b[0] in JCC8:
            kind = ('short', b[0], b[1])
        elif len(b) >= 6 and b[0] == 0x0f and b[1] in JCC32:
            kind = ('near', b[1], struct.unpack('<i', b[2:6])[0])
        if not kind:
            continue
        ctx = insns[max(0, idx-3):idx]
        ctx_txt = ' ; '.join(f'{c.mnemonic} {c.op_str}'.strip() for c in ctx)
        if not re.search(r'\b(test|cmp|call|or|and|xor)\b', ctx_txt):
            continue
        target_va = insn.address

