## 二、检测代码（C，跨 GCC/MSVC）

### 1. CPUID 虚拟机位 + 厂商串

```c
/* anti_vm_cpuid.c — gcc: cc anti_vm_cpuid.c ; msvc: cl anti_vm_cpuid.c */
#include <stdio.h>
#include <string.h>
#include <stdint.h>
#if defined(_MSC_VER)
#  include <intrin.h>
#else
#  include <cpuid.h>
#endif

static void cpuid_ex(uint32_t leaf, uint32_t sub,
                     uint32_t *a, uint32_t *b, uint32_t *c, uint32_t *d) {
#if defined(_MSC_VER)
    int r[4]; __cpuidex(r, leaf, sub);
    *a=r[0]; *b=r[1]; *c=r[2]; *d=r[3];
#else
    __cpuid_count(leaf, sub, *a, *b, *c, *d);
#endif
}

/* leaf 1, ECX bit31 = "hypervisor present" */
int hv_present(void) {
    uint32_t a,b,c,d; cpuid_ex(1, 0, &a,&b,&c,&d);
    return (c >> 31) & 1;
}

/* leaf 0x40000000 返回 12 字节厂商串 */
void hv_vendor(char out[13]) {
    uint32_t a,b,c,d; cpuid_ex(0x40000000, 0, &a,&b,&c,&d);
    memcpy(out+0,&b,4); memcpy(out+4,&c,4); memcpy(out+8,&d,4); out[12]=0;
}
/*   VMwareVMware / KVMKVMKVM / VBoxVBoxVBox / Microsoft Hv / XenVMMXenVMM */

/* leaf 0x40000001 返回 capability，可区分 VBox 版本等 */
int main(void) {
    char v[13] = {0};
    if (hv_present()) { hv_vendor(v); printf("hypervisor: %s\n", v); }
    else              printf("no hypervisor bit\n");
    return 0;
}
```

### 2. VMware backdoor 端口 0x5658

```c
/* x86/x64 专用。非 VMware 宿主上 IN 到 0x5658 会原样返回
   或不设置 EBX；VMware 上 EBX 回填 magic 0x564D5868 */
int vmware_backdoor(void) {
    uint32_t eax = 0x564D5868;      /* "VMXh" */
    uint32_t ebx = 0xFFFFFFFF;
    uint32_t ecx = 0x0A;            /* GETVERSION */
    uint32_t edx = 0x5658;
    __asm__ volatile("inl %%dx, %%eax"
        : "+a"(eax), "+b"(ebx), "+c"(ecx)
        : "d"(edx));
    return ebx == 0x564D5868;
}
```

### 3. MAC OUI 检查（Windows `GetAdaptersAddresses`）

```c
/* cl mac_check.c iphlpapi.lib ws2_32.lib */
#include <winsock2.h>
#include <iphlpapi.h>
#include <stdio.h>
#pragma comment(lib, "iphlpapi.lib")
#pragma comment(lib, "ws2_32.lib")

static const unsigned char OUI[][3] = {
    {0x00,0x05,0x69},{0x00,0x0C,0x29},{0x00,0x1C,0x14},{0x00,0x50,0x56}, /* VMware  */
    {0x08,0x00,0x27},                          /* VirtualBox */
    {0x52,0x54,0x00},                          /* QEMU/KVM   */
    {0x00,0x16,0x3E},                          /* Xen        */
    {0x00,0x15,0x5D},                          /* Hyper-V    */
};
int mac_check(void) {
    ULONG sz = 16*1024; IP_ADAPTER_ADDRESSES *aa = malloc(sz);
    if (GetAdaptersAddresses(AF_UNSPEC, 0, NULL, aa, &sz) != NO_ERROR) return 0;
    for (IP_ADAPTER_ADDRESSES *p = aa; p; p = p->Next) {
        if (p->PhysicalAddressLength < 3) continue;
        for (int i = 0; i < (int)(sizeof OUI/sizeof OUI[0]); i++)
            if (!memcmp(p->PhysicalAddress, OUI[i], 3)) { free(aa); return 1; }
    }
    free(aa); return 0;
}
```

