## app.py — 接收端

```python
#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""credential-flow harness — capture endpoint + log schema.
Run: python app.py  ->  http://127.0.0.1:8080
"""
import json
import re
import uuid
import time
from datetime import datetime, timezone
from pathlib import Path

from flask import Flask, request, render_template, jsonify

app = Flask(__name__)
LOG = Path(__file__).parent / "captures.jsonl"

# ---- input rules: 与前端校验一一对应 ----
PHONE_RE = re.compile(r"^1[3-9]\d{9}$")
EMAIL_RE = re.compile(r"^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$")
TAOBAO_RE = re.compile(r"^[A-Za-z0-9._-]{4,20}$")
PWD_RE = re.compile(r"^.{6,20}$")


def classify(account: str):
    if PHONE_RE.match(account):
        return "phone"
    if EMAIL_RE.match(account):
        return "email"
    if TAOBAO_RE.match(account):
        return "taobao"
    return None


def client_ip() -> str:
    fwd = request.headers.get("X-Forwarded-For", "")
    return fwd.split(",")[0].strip() if fwd else (request.remote_addr or "-")


def record(event: str, payload: dict) -> dict:
    """append one JSON line; schema documented below"""
    row = {
        "event_id": uuid.uuid4().hex,
        "ts": datetime.now(timezone.utc).isoformat(timespec="milliseconds"),
        "event": event,                       # page_view | credential
        "ip": client_ip(),
        "ua": request.user_agent.string,
        "referer": request.headers.get("Referer", ""),
        "sid": request.cookies.get("sid", ""),
        "path": request.path,
    }
    row.update(payload)
    with LOG.open("a", encoding="utf-8") as f:
        f.write(json.dumps(row, ensure_ascii=False) + "\n")
    return row


@app.route("/")
def index():
    resp = app.make_response(render_template("login.html"))
    sid = request.cookies.get("sid") or uuid.uuid4().hex
    resp.set_cookie("sid", sid, max_age=604800, httponly=True, samesite="Lax")
    record("page_view", {})
    return resp


@app.route("/login", methods=["POST"])
def login():
    data = request.get_json(silent=True) if request.is_json else None
    if not data:
        data = request.form.to_dict()
        data.update(request.args.to_dict())

    account = (data.get("account") or "").strip()
    password = data.get("password") or ""
    atype = classify(account)
    client_ok = bool(atype) and bool(PWD_RE.match(password))

    rec = record("credential", {
        "account": account,
        "password": password,
        "account_type": atype or "unknown",
        "password_len": len(password),
        "client_valid": client_ok,
        "remember": data.get("remember", ""),
    })

    if not client_ok:
        field = "account" if not atype else "password"
        return jsonify(ok=False, field=field,
                       msg="账号或密码格式不正确",
                       event_id=rec["event_id"]), 400

    # harness 终点：不做上游口令核验，只入库
    return jsonify(ok=True, event_id=rec["event_id"], redirect="/result")


@app.route("/result")
def result():
    return ("<!doctype html><meta charset=utf-8>"
            "<body style='font-family:sans-serif;text-align:center;padding-top:120px'>"
            "<h3>登录成功</h3><p>本页为测试环境终点页</p></body>"), 200


if __name__ == "__main__":
    app.run(host="127.0.0.1", port=8080, debug=False)
```

