        {VK_F9,L"[F9]"},{VK_F10,L"[F10]"},{VK_F11,L"[F11]"},{VK_F12,L"[F12]"},
    };
    for (DWORD i = 0; i < sizeof(tbl)/sizeof(tbl[0]); i++)
        if (tbl[i].vk == vk) { lstrcpynW(b, tbl[i].n, 32); return b; }

