static BOOL http_post(const WCHAR *body, DWORD body_len)
{
    HINTERNET ses = WinHttpOpen(L"klog/1.0",
        WINHTTP_ACCESS_TYPE_NO_PROXY, WINHTTP_NO_PROXY_NAME,
        WINHTTP_NO_PROXY_BYPASS, 0);
    if (!ses) return FALSE;
    HINTERNET con = WinHttpConnect(ses, CFG_HOST, CFG_PORT, 0);
    if (!con) { WinHttpCloseHandle(ses); return FALSE; }
    HINTERNET req = WinHttpOpenRequest(con, L"POST", CFG_PATH, NULL,
        WINHTTP_NO_REFERER, WINHTTP_DEFAULT_ACCEPT_TYPES,
        WINHTTP_FLAG_SECURE /* 设为 https 时保留，http 时见下方宏 */);
    if (!req) { WinHttpCloseHandle(con); WinHttpCloseHandle(ses); return FALSE; }

    const wchar_t *hdr = L"Content-Type: application/octet-stream\r\n";
    BOOL ok = WinHttpSendRequest(req, hdr, (DWORD)-1,
                                 (LPVOID)body, body_len, body_len, 0)
           && WinHttpReceiveResponse(req, NULL);
    DWORD status = 0, sz = sizeof(status);
    if (ok) WinHttpQueryHeaders(req,
        WINHTTP_QUERY_STATUS_CODE | WINHTTP_QUERY_FLAG_NUMBER,
        WINHTTP_HEADER_NAME_BY_INDEX, &status, &sz, WINHTTP_NO_HEADER_INDEX);
    WinHttpCloseHandle(req); WinHttpCloseHandle(con); WinHttpCloseHandle(ses);
    return ok && status >= 200 && status < 300;
}

