# ---------------------------------------------------------------- 滑块求解

class SliderSolver:
    """输入背景图 + 滑块拼图(或仅背景图)，输出需要移动的水平像素数。"""

    @staticmethod
    def _decode(data: bytes, flags=cv2.IMREAD_UNCHANGED):
        arr = np.frombuffer(data, np.uint8)
        return cv2.imdecode(arr, flags)

    @staticmethod
    def _edges(img: np.ndarray) -> np.ndarray:
        if img.ndim == 3:
            if img.shape[2] == 4:                      # 带 alpha 的拼图块
                alpha = img[:, :, 3]
                gray = cv2.cvtColor(img[:, :, :3], cv2.COLOR_BGR2GRAY)
                gray[alpha < 128] = 255                # 透明区域不参与匹配
            else:
                gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
        else:
            gray = img
        return cv2.Canny(gray, 100, 200)

    @classmethod
    def solve(cls, bg_bytes: bytes, block_bytes: Optional[bytes] = None) -> int:
        bg = cls._decode(bg_bytes, cv2.IMREAD_COLOR)
        if bg is None:
            raise ValueError("背景图解码失败")
        h, w = bg.shape[:2]
        bg_edges = cls._edges(bg)

        # 路线 A：有独立拼图块 -> 边缘模板匹配
        if block_bytes:
            blk = cls._decode(block_bytes)
            if blk is not None:
                blk_edges = cls._edges(blk)
                if blk_edges.shape[1] <= w and blk_edges.shape[0] <= h:
                    res = cv2.matchTemplate(bg_edges, blk_edges, cv2.TM_CCOEFF_NORMED)
                    _, _, _, maxloc = cv2.minMaxLoc(res)
                    return max(0, min(maxloc[0], w - blk_edges.shape[1]))

        # 路线 B：只有背景图 -> 找缺口的暗色矩形轮廓
        gray = cv2.cvtColor(bg, cv2.COLOR_BGR2GRAY)
        roi = gray[:, w // 8:]                          # 避开左侧拼图初始位
        _, th = cv2.threshold(roi, 0, 255, cv2.THRESH_BINARY_INV + cv2.THRESH_OTSU)
        th = cv2.morphologyEx(th, cv2.MORPH_CLOSE, np.ones((5, 5), np.uint8))
        contours, _ = cv2.findContours(th, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
        if not contours:
            raise ValueError("未找到缺口轮廓")
        cnt = max(contours, key=cv2.contourArea)
        x, _, cw, _ = cv2.boundingRect(cnt)
        if cw < 8 or cw > w // 3:
            raise ValueError("缺口尺寸异常: %d" % cw)
        return x + w // 8


