class InboxPollProvider:
    """轮询自建短信/邮件网关的收件接口：GET {url}?phone=xxx -> {"code": "123456"}"""

    def __init__(self, url: str, token: str = "", timeout: int = 60, interval: float = 2.0):
        self.url, self.token = url, token
        self.timeout, self.interval = timeout, interval

    def get_code(self, phone: str) -> str:
        deadline = time.time() + self.timeout
        headers = {"Authorization": "Bearer " + self.token} if self.token else {}
        while time.time() < deadline:
            r = requests.get(self.url, params={"phone": phone}, headers=headers, timeout=10)
            if r.ok:
                data = r.json()
                code = str(data.get("code") or "").strip()
                if code:
                    return code
            time.sleep(self.interval)
        raise TimeoutError("收件网关超时: %s" % phone)


