## 3. libc 层：`cloak.c`（LD_PRELOAD，补漏网调用）

```c
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>
#include <sys/utsname.h>
#include <unistd.h>

/* 路径映射表: 真实路径 -> 替换内容(若为 NULL 则文件表现为不存在) */
static const struct { const char *real; const char *fake; } MAP[] = {
  {"/proc/cpuinfo",   NULL},                    /* 由 ns 层处理，这里屏蔽直读 */
  {"/sys/class/dmi/id/sys_vendor", "Dell Inc.\n"},
  {"/sys/class/dmi/id/product_name", "Latitude 7490\n"},
  {"/sys/class/dmi/id/board_name", "0F6C8\n"},
  {"/sys/class/dmi/id/bios_vendor", "Dell Inc.\n"},
  {"/sys/module/kvm",        NULL},
  {"/sys/module/vboxguest",  NULL},
  {"/sys/module/vmware",     NULL},
  {"/proc/scsi/scsi",        NULL},             /* 常见 VM 虚拟磁盘签名 */
};

static const char *lookup(const char *path) {
  for (size_t i = 0; i < sizeof(MAP)/sizeof(MAP[0]); i++)
    if (strcmp(path, MAP[i].real) == 0) return MAP[i].fake;
  return NULL;
}

/* 被屏蔽的路径用 /dev/null 假内容流替代 */
FILE *fopen(const char *path, const char *mode) {
  static FILE *(*real_fopen)(const char *, const char *) = NULL;
  if (!real_fopen) real_fopen = dlsym(RTLD_NEXT, "fopen");
  const char *fake = lookup(path);
  if (fake == NULL && lookup(path) != NULL) {      /* 完全屏蔽: 表现为 EACCES 等价 */
    static FILE *nullf = NULL;
    if (!nullf) nullf = fopen("/dev/null", mode);
    rewind(nullf);
    return nullf;
  }
  if (fake) {
    /* 返回一个仅含伪造内容的内存流 */
    return fmemopen((void *)fake, strlen(fake), mode);
  }
  return real_fopen(path, mode);
}
FILE *fopen64(const char *path, const char *mode) { return fopen(path, mode); }

int open(const char *path, int flags, ...) {
  static int (*real_open)(const char *, int, ...) = NULL;
  if (!real_open) real_open = dlsym(RTLD_NEXT, "open");
  const char *fake = lookup(path);
  if (fake) {
    char tmpl[] = "/tmp/.clkXXXXXX";
    int fd = mkstemp(tmpl);
    write(fd, fake, strlen(fake));
    lseek(fd, 0, SEEK_SET);
    unlink(tmpl);          /* 内容仍在 fd 上，路径已消失 */
    return fd;
  }
  if (fake == NULL) {
    /* 屏蔽类: 让目标收到 ENOENT */
    static int devnull = -1;
    if (devnull < 0) devnull = open("/dev/null", O_RDONLY);
    return devnull;
  }
  return real_open(path, flags, 0644);
}

/* 主机名伪装: 桌面风格而非 DESKTOP-XXXX / vm-xxx */
int uname(struct utsname *u) {
  static int (*real_uname)(struct utsname *) = NULL;
  if (!real_uname) real_uname = dlsym(RTLD_NEXT, "uname");
  int r = real_uname(u);
  if (r == 0) {
    strncpy(u->nodename,  "workstation-07", sizeof(u->nodename)-1);
    strncpy(u->release,   "5.15.0-78-generic", sizeof(u->release)-1);
    strncpy(u->version,   "#85-Ubuntu SMP Fri Jul 7 00:29:46 UTC 2023",
            sizeof(u->version)-1);
    strncpy(u->machine,   "x86_64", sizeof(u->machine)-1);
  }
  return r;
}

/* 反测子壳: 目标常执行 "systemd-detect-virt" / "lsmod | grep vm" 探测 */
int system(const char *cmd) {
  static int (*real_system)(const char *) = NULL;
  if (!real_system) real_system = dlsym(RTLD_NEXT, "system");
  if (cmd && (strstr(cmd, "detect-virt") || strstr(cmd, "virt-what")
           || strstr(cmd, "vmware") || strstr(cmd, "vbox"))) {
    /* 直接给出 "none" 语义: 写 stdout 后返回 1(未检测到虚拟化) */
    fputs("none\n", stdout);
    return 1;
  }
  return real_system(cmd);
}
