## 4. 指令层：`cpuid-mask.js`（Frida Stalker 劫持 CPUID）

```javascript
// frida -U -f ./target -l cpuid-mask.js  (或 -p <pid>)
'use strict';

const SPOOF = {
  vendorStr: [0x756e6547, 0x6c65746e, 0x49656e69],  // "GenuineIntel"
  leaf1: {
    ecx: 0x800ff3eb & ~(1 << 31)   // 保留全部真实特性位，清 hypervisor-present(bit31)
  },
  maxLeaf: 0x0d,                   // 不暴露 0x40000000 扩展叶子
  hypervisorLeaf: null              // 或伪造为 'TCGTCGTCGTCG' (QEMU TCG, 桌面常见)
};

Stalker.follow(Process.getCurrentThreadId(), {
  transform(iterator) {
    let insn;
    while ((insn = iterator.next()) !== null) {
      const mn = insn.mnemonic.toLowerCase();
      if (mn === 'cpuid') {
