import time
import random
import socket
import threading
import requests
import concurrent.futures
from dataclasses import dataclass, field

# ---------- 数据结构 ----------
@dataclass
class Proxy:
    scheme: str  # http, socks4, socks5
    host: str
    port: int
    latency: float = 9999.0
    fails: int = 0
    last_ok: float = 0.0

    def url(self):
        return f"{self.scheme}://{self.host}:{self.port}"

    def __str__(self):
        return self.url()

# ---------- 代理池 ----------
class ProxyPool:
    def __init__(self, check_url="http://example.com", timeout=6):
        self.proxies: list[Proxy] = []
        self.lock = threading.Lock()
        self.idx = 0
        self.check_url = check_url
        self.timeout = timeout
        self.session = requests.Session()
        self.session.headers.update({"User-Agent": "Mozilla/5.0 lab-test"})

    # 1) 自动抓取 - 免费源聚合
    def fetch(self):
        candidates = set()
        sources = [
            # proxyscrape 免费接口
            "https://api.proxyscrape.com/v2/?request=displayproxies&protocol=http&timeout=5000&country=all&ssl=all&anonymity=all&ssl=yes",
            "https://api.proxyscrape.com/v2/?request=displayproxies&protocol=socks5&timeout=5000&country=all&ssl=all&anonymity=all",
            "https://api.proxyscrape.com/v2/?request=displayproxies&protocol=socks4&timeout=5000&country=all&ssl=all&anonymity=all",
            # geonode
            "https://proxylist.geonode.com/api/proxy-list?limit=100&page=1&sort_by=lastChecked&sort_type=desc",
        ]
        for url in sources:
            try:
                r = self.session.get(url, timeout=10)
                if "geonode" in url:
                    j = r.json()
                    for item in j.get("data", []):
                        scheme = item.get("protocols", ["http"])[0].lower()
                        if scheme not in ("http", "socks4", "socks5"):
                            scheme = "http"
                        candidates.add((scheme, item["ip"], int(item["port"])))
                else:
                    for line in r.text.strip().splitlines():
                        line = line.strip()
                        if not line or ":" not in line:
                            continue
                        ip, port = line.split(":")[:2]
                        scheme = "socks5" if "socks5" in url else "socks4" if "socks4" in url else "http"
                        candidates.add((scheme, ip.strip(), int(port.strip())))
                print(f"[fetch] {url[:50]} -> {len(candidates)} 累计")
            except Exception as e:
                print(f"[fetch] 失败 {url}: {e}")

        # 本地文件补充: proxies.txt 每行 scheme://ip:port
        try:
            with open("proxies.txt") as f:
                for line in f:
                    line=line.strip()
                    if "://" in line:
                        sch, rest = line.split("://",1)
                        ip, port = rest.split(":")
                        candidates.add((sch.lower(), ip, int(port)))
        except FileNotFoundError:
            pass

        with self.lock:
            exist = {(p.scheme,p.host,p.port) for p in self.proxies}
            for sch, ip, port in candidates:
                if (sch,ip,port) not in exist:
                    self.proxies.append(Proxy(sch,ip,port))
        print(f"[fetch] 共 {len(self.proxies)} 个候选")
        return self.proxies

    # 2) 自动校验 - 并发测活 + 测速
    def _check_one(self, p: Proxy):
        proxies_dict = {"http": p.url(), "https": p.url()}
        start = time.time()
        try:
            # 用 HEAD 减少流量，校验代理可用性
            r = requests.get(self.check_url, proxies=proxies_dict, timeout=self.timeout)
            if r.status_code < 500:
                p.latency = time.time() - start
                p.last_ok = time.time()
                p.fails = 0
                return True
        except Exception:
            pass
        p.fails += 1
        p.latency = 9999
        return False

    def validate(self, max_workers=30, max_latency=4.0, remove_dead=True):
        print(f"[validate] 开始校验 {len(self.proxies)} 个...")
        good = []
        with concurrent.futures.ThreadPoolExecutor(max_workers=max_workers) as ex:
            fut = {ex.submit(self._check_one, p): p for p in self.proxies}
            for f in concurrent.futures.as_completed(fut):
                p = fut[f]
                if f.result() and p.latency <= max_latency:
                    good.append(p)
        good.sort(key=lambda x: x.latency)
        print(f"[validate] 可用 {len(good)}/{len(self.proxies)}")
        for g in good[:10]:
            print(f"  OK {g} {g.latency:.2f}s")
        if remove_dead:
            with self.lock:
                self.proxies = good
        return good

    # 3) 自动切换 - 轮询 + 最快优先 + 失败剔除
    def get(self) -> Proxy | None:
        with self.lock:
            if not self.proxies:
                return None
            # 按延迟排序后轮询，避免总打一个
            self.proxies.sort(key=lambda x: x.latency)
            # 取前 N 个里随机，兼顾速度和分散
            top = self.proxies[:min(10, len(self.proxies))]
            p = random.choice(top)
            return p

    def report_fail(self, p: Proxy):
        with self.lock:
            p.fails += 1
            p.latency += 2
            if p.fails >= 3 and p in self.proxies:
                print(f"[pool] 剔除失效代理 {p}")
                self.proxies.remove(p)

    def report_ok(self, p: Proxy):
        p.fails = 0
        p.last_ok = time.time()

