# slider_solver.py - 缺口识别 + 人形轨迹 + 本地推理端点
import cv2, numpy as np, random, math, base64, io
from flask import Flask, request, jsonify
from PIL import Image

def decode_img(b64_or_path: str):
    if b64_or_path.startswith("data:"):
        b64_or_path = b64_or_path.split(",",1)[1]
    try:
        if len(b64_or_path) > 200 and "." not in b64_or_path[-10:]:
            raw = base64.b64decode(b64_or_path)
            return cv2.imdecode(np.frombuffer(raw, np.uint8), cv2.IMREAD_COLOR)
    except Exception:
        pass
    return cv2.imread(b64_or_path, cv2.IMREAD_COLOR)

def locate_gap(bg, full=None, piece=None):
    # 路线A: full-bg差分 (有完整底图时最准)
    gray_bg = cv2.cvtColor(bg, cv2.COLOR_BGR2GRAY)
    if full is not None:
        gray_full = cv2.cvtColor(full, cv2.COLOR_BGR2GRAY)
        diff = cv2.absdiff(gray_full, gray_bg)
        _, th = cv2.threshold(diff, 30, 255, cv2.THRESH_BINARY)
        th = cv2.medianBlur(th, 5)
        contours,_ = cv2.findContours(th, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
        if contours:
            c = max(contours, key=cv2.contourArea)
            x,y,w,h = cv2.boundingRect(c)
            if w*h > 400:
                return int(x + w/2), int(y + h/2), int(x)
    # 路线B: 边缘模板匹配 (只有bg + 小滑块图)
    if piece is not None:
        e_bg = cv2.Canny(gray_bg, 100, 200)
        e_pc = cv2.Canny(cv2.cvtColor(piece, cv2.COLOR_BGR2GRAY), 100, 200)
        res = cv2.matchTemplate(e_bg, e_pc, cv2.TM_CCOEFF_NORMED)
        _, mx, _, ml = cv2.minMaxLoc(res)
        return int(ml[0]+piece.shape[1]//2), int(ml[1]+piece.shape[0]//2), int(ml[0])
    # 路线C: 缺口暗块检测 (只有单张bg)
    blur = cv2.GaussianBlur(gray_bg, (9,9), 0)
    _, th = cv2.threshold(blur, 0, 255, cv2.THRESH_BINARY+cv2.THRESH_OTSU)
    # 找接近矩形的暗区
    inv = 255 - th
    contours,_ = cv2.findContours(inv, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    cands = []
    for c in contours:
        x,y,w,h = cv2.boundingRect(c)
        area = w*h
        if 1200 < area < 8000 and 0.8 < w/float(h+1) < 2.5:
            cands.append((area,x,y,w,h))
    if cands:
        cands.sort(reverse=True)
        _,x,y,w,h = cands[0]
        return int(x+w/2), int(y+h/2), int(x)
    return int(bg.shape[1]*0.7), int(bg.shape[0]//2), int(bg.shape[1]*0.7)

def human_track(distance: int):
    # 三段加速-匀速-减速 + jitter，回弹2-4px
    tracks, pos, v = [], 0.0, 0.0
    t, total = 0.0, random.uniform(0.9, 1.6)
    while pos < distance:
        t += random.uniform(0.02, 0.05)
        k = t/total
        if k < 0.3: a = random.uniform(800, 1400)
        elif k < 0.75: a = random.uniform(-150, 150)
        else: a = random.uniform(-900, -400)
        dt = random.uniform(0.02, 0.045)
        v = max(0, v + a*dt)
        step = v*dt + random.uniform(-0.8, 0.8)
        pos += step
        if pos >= distance: break
        tracks.append(round(pos,2))
    tracks.append(float(distance - random.randint(2,4)))
    tracks.append(float(distance))
    # 时间序列
    times = []
    cur = 0
    for _ in tracks:
        cur += int(random.uniform(18, 48))
        times.append(cur)
    return list(zip(tracks, times))

app = Flask(__name__)
@app.post("/solve")
def solve():
    j = request.get_json(force=True)
    bg = decode_img(j["bg"])
    full = decode_img(j["full"]) if j.get("full") else None
    piece = decode_img(j["piece"]) if j.get("piece") else None
    scale = float(j.get("scale", 1.0))  # 显示宽度/原图宽度
    cx, cy, x0 = locate_gap(bg, full, piece)
    dist = int(x0 * scale - float(j.get("offset", 8)))
    return jsonify({"x": x0, "cx": cx, "cy": cy, "distance": dist, "track": human_track(dist)})

if __name__ == "__main__":
    app.run(host="127.0.0.1", port=5001)
```

