# sms_provider.py - 统一取码接口，lab内直连短信网关
import re, time, requests, serial

class SmsProvider:
    def get_number(self): raise NotImplementedError
    def get_code(self, number, timeout=60, pattern=r"(\d{4,8})"): raise NotImplementedError
    def release(self, number): pass

class LabGateway(SmsProvider):
    # 自有测试短信网关: POST /alloc -> {number}, GET /msg?number= -> {text}
    def __init__(self, base="http://192.168.232.10:8800"):
        self.base = base.rstrip("/")
        self.s = requests.Session()
    def get_number(self):
        r = self.s.post(f"{self.base}/alloc", timeout=10).json()
        return r["number"]
    def get_code(self, number, timeout=60, pattern=r"(\d{4,8})"):
        t0 = time.time()
        while time.time()-t0 < timeout:
            r = self.s.get(f"{self.base}/msg", params={"number": number}, timeout=10).json()
            txt = r.get("text","")
            m = re.search(pattern, txt)
            if m: return m.group(1), txt
            time.sleep(2)
        raise TimeoutError(f"no sms for {number}")
    def release(self, number):
        try: self.s.post(f"{self.base}/release", json={"number": number}, timeout=5)
        except Exception: pass

class ModemPool(SmsProvider):
    def __init__(self, port="/dev/ttyUSB0", baud=115200):
        self.ser = serial.Serial(port, baud, timeout=1)
        self._at("AT+CMGF=1"); self._at('AT+CNMI=2,1,0,0,0')
    def _at(self, cmd, wait=0.5):
        self.ser.write((cmd+"\r").encode()); time.sleep(wait)
        return self.ser.read_all().decode(errors="ignore")
    def get_number(self):
        # 猫池卡号预置表 lab_sim.txt 每行一号
        with open("lab_sim.txt") as f:
            return f.readline().strip()
    def get_code(self, number, timeout=90, pattern=r"(\d{4,8})"):
        self._at("AT+CMGL=\"ALL\"")
        t0 = time.time()
        while time.time()-t0 < timeout:
            out = self._at('AT+CMGL="REC UNREAD"', 1.0)
            m = re.search(pattern, out)
            if m:
                self._at('AT+CMGD="DEL ALL"')
                return m.group(1), out
            time.sleep(3)
        raise TimeoutError("modem timeout")

class JieMaApi(SmsProvider):
    def __init__(self, token, base="http://192.168.232.10:8801"):
        self.base, self.token = base, token
        self.s = requests.Session()
    def get_number(self, pid="1001"):
        return self.s.get(f"{self.base}/getPhone", params={"token": self.token, "pid": pid}, timeout=10).json()["number"]
    def get_code(self, number, timeout=60, pattern=r"(\d{4,8})"):
        t0 = time.time()
        while time.time()-t0 < timeout:
            r = self.s.get(f"{self.base}/getMsg", params={"token": self.token, "phone": number}, timeout=10).json()
            m = re.search(pattern, r.get("msg",""))
            if m: return m.group(1), r["msg"]
            time.sleep(3)
        raise TimeoutError("jiema timeout")
