 * 用途：在你的自有客户端上建立可验证的完整性基线，用于研究"检测方如何检测"
 * 说明：功能是"发现并记录篡改"，不是"隐藏篡改"。
 * Build:  WDK / MSVC x64, /GS, /GUARD:CF, Control Flow Guard = Yes
 * ---------------------------------------------------------------------- */
#include <ntddk.h>
#include <ntstrsafe.h>

#define TG_TAG 'gTaP'
#define TG_MAX_EVENTS 512

/* ---- 事件类型：覆盖内核侧可观测的篡改面 --------------------------------- */
typedef enum _TG_EVENT {
    TG_EVT_NONE = 0,
    TG_EVT_HANDLE_OPEN = 1,  /* 有进程申请对本进程 VM_READ/VM_WRITE   */
    TG_EVT_IMAGE_LOAD     = 2,  /* 未签名模块被加载进本进程              */
    TG_EVT_MEM_EXEC = 3,  /* 私有 RX 页出现（注入特征）            */
    TG_EVT_DR_REGISTER     = 4,  /* DR0-DR3 被设置（硬件断点=调试器）     */
    TG_EVT_THREAD_START    = 5,  /* 线程起始地址不在任何模块映像内 */
    TG_EVT_MSR_HOOK        = 6,  /* IA32_LSTAR / STAR 被改写             */
    TG_EVT_DISPATCH_HOOK   = 7,  /* 内核分发表被 inline hook             */
    TG_EVT_CFG_VIOLATION   = 8,  /* CFG 间接调用越界                     */
    TG_EVT_MODULE_MISMATCH = 9   /* 用户态/内核态模块视图不一致          */
} TG_EVENT;

typedef struct _TG_RECORD {
    ULONGLONG            Timestamp;
    TG_EVENT              Event;
    ULONG                 Pid;
    PETHREAD Requestor;   /* 发起句柄操作的线程          */
    PVOID                 Address;      /* 相关地址（可选）            */
    ULONG                 RequestorPid;
    WCHAR                 Detail[96];
} TG_RECORD, *PTG_RECORD;

static TG_RECORD  g_Events[TG_MAX_EVENTS];
static volatile LONG g_EventCount = 0;
static PDEVICE_OBJECT g_Dev = NULL;

/* 全局受保护进程列表（你的游戏客户端主进程） */
typedef struct _TG_TARGET {
    HANDLE    Pid;
    PEPROCESS Process;
    LIST_ENTRY Link;
} TG_TARGET, *PTG_TARGET;

static LIST_ENTRY g_Targets = { &g_Targets, &g_Targets };

/* ---- 事件记录 ---------------------------------------------------------- */
static VOID Tg_Log(TG_EVENT Ev, PEPROCESS Req, PVOID Addr, PCWSTR Fmt, ...)
{
    LARGE_INTEGER Tick; ULONG idx; va_list ap; TG_RECORD *r;
    if (InterlockedIncrement(&g_EventCount) > TG_MAX_EVENTS) {
        InterlockedDecrement(&g_EventCount);
        return;
    }
    idx = (ULONG)((ULONG_PTR)&Ev % TG_MAX_EVENTS);
    r = &g_Events[idx];
    KeQueryTickCount(&Tick);
    r->Timestamp = (ULONGLONG)Tick.QuadPart;
    r->Event      = Ev;
    r->Address = Addr;
    r->Requestor  = PsGetCurrentProcess();
    r->RequestorPid = PsGetCurrentProcessId();

    {
        PKPROCESS p = PsGetCurrentProcess();
        /* 记录发起者 PID */
        OBJECT_ATTRIBUTES oa = { sizeof(oa) };
        PPROCESS_HEADER ph = (PPROCESS_HEADER)(ULONG_PTR)p;
        (void)ph;
        r->RequestorPid = (ULONG)PsGetCurrentProcessId();
    }
    va_start(ap, Fmt);
    RtlStringCbPrintfW(r->Detail, 96, Fmt, ap);
    va_end(ap);
}

/* ---- 面 1：句柄访问监控 ------------------------------------------------ */
/* 这是"游戏内存读取类"外挂在内核侧最早暴露的一环，也是腾讯系反作弊
 * 最常用的策略：对未授权签名/低信任进程剥离 VM_READ。 */
static NTSTATUS Tg_ObFilter(PUNICODE_STRING pcu, POBJECT_TYPE ot,
                             PACCESS_MASK am, PACCESS_MODE cm)
{
    if (ot != *PsProcessType) {
        return STATUS_SUCCESS;
    }
    /* 若目标是我们登记的受保护进程，且申请者不是自身内核组件，则降权 */
    if ((*am & (VM_READ | VM_WRITE | VM_OPERATION)) && PsGetCurrentProcessId() != 4) {
        /* 生产策略：剥离写权限并强制审计（保留读以便自身调试工具） */
        *am &= ~(VM_WRITE | VM_OPERATION);
        Tg_Log(TG_EVT_HANDLE_OPEN, NULL, NULL,
               L"handle: pid=%u requested VM_READ/VM_WRITE on protected target, downgraded",
               PsGetCurrentProcessId());
    }
    return STATUS_SUCCESS;
}

