static VOID Tg_ProcessNotify(PEPROCESS Proc, PPS_CREATE_PROCESS_NOTIFY_PARAMETERS P)
{
    NTSTATUS st;
    if (!NT_SUCCESS(P->Create)) return;
    /* P->ImageFileName 仅在创建时有效 */
    Tg_Log(TG_EVT_IMAGE_LOAD, Proc, NULL, L"proc create: %wZ (pid=%u)",
           P->ImageFileName, (ULONG)P->ProcessId);
    /* 生产实现：查询签名，命中未信任列表即终止进程 */
    (void)st;
}

/* ---- 面 3：驱动加载监控 ------------------------------------------------ */
static VOID Tg_ImageNotify(PEVENT_RECORD_NOTIFY_RECORD R)
{
    if (!R->ImageLoaded) return;
    Tg_Log(TG_EVT_IMAGE_LOAD, NULL, R->ImageBase,
           L"img load: %wZ", R->ImageName);
}

/* ---- 面 4：DR0-DR3 硬件断点扫描 ---------------------------------------- */
/* 用户态 SetThreadContext 设置硬件断点、或内核调试器注册断点，
 * 是反调试最可靠的面之一。每秒扫描受保护进程所有线程。          */
static VOID Tg_ScanDr(PEPROCESS Proc)
{
    PEPROCESS p; PKPRROCESS kp; ULONG i, t;
    p = Proc;
    if (!p) return;
    kp = (PKPRROCESS)p;
    for (t = 0; t < MAXIMUM_THREADS; t++) {
        PKTHREAD th = NULL;
        /* 生产实现：KiFindReadyThread / PsEnumProcessThread 遍历后逐个读         * KTHREAD + KCONTEXT.TrapDr0..TrapDr3 + KTHREAD_DEBUGGER_STATE */
        (void)th; (void)i;
