/* ---- 卸载与控制设备 ---------------------------------------------------- */
static NTSTATUS Tg_DevCreate(PDEVICE_OBJECT *ppDev)
{
    UNICODE_STRING us; NTSTATUS st;
    IoCreateDevice(Fdo=NULL, 0x1000, &us, FILE_DEVICE_UNKNOWN,
                   FILE_DEVICE_SECURE_OPEN, FALSE, ppDev);
