# ---------------------------------------------------------------- mmh3
def mmh3_32(data: bytes, seed: int = 0) -> int:
    c1, c2 = 0xcc9e2d51, 0x1b873593
    length = len(data); h = seed & 0xffffffff; rounded = length & 0xfffffffc
    for i in range(0, rounded, 4):
        k = data[i] | (data[i + 1] << 8) | (data[i + 2] << 16) | (data[i + 3] << 24)
        k = (k * c1) & 0xffffffff
        k = ((k << 15) | (k >> 17)) & 0xffffffff
        k = (k * c2) & 0xffffffff
        h ^= k
        h = ((h << 13) | (h >> 19)) & 0xffffffff
        h = (h * 5 + 0xe6546b64) & 0xffffffff
    k = 0; tail = length & 3
    if tail >= 3: k ^= data[rounded + 2] << 16
    if tail >= 2: k ^= data[rounded + 1] << 8
    if tail >= 1:
        k ^= data[rounded]
        k = (k * c1) & 0xffffffff
        k = ((k << 15) | (k >> 17)) & 0xffffffff
        k = (k * c2) & 0xffffffff
        h ^= k
    h ^= length
    h ^= h >> 16; h = (h * 0x85ebca6b) & 0xffffffff
    h ^= h >> 13; h = (h * 0xc2b2ae35) & 0xffffffff
    h ^= h >> 16
    return h - 0x100000000 if h & 0x80000000 else h


def favicon_hash(session: requests.Session, base: str):
    """返回 Shodan/FOFA 风格 favicon mmh3 哈希，None 表示取不到"""
    try:
        r = session.get(urljoin(base, "/favicon.ico"), timeout=12, verify=False)
        if r.status_code == 200 and r.content:
            return mmh3_32(base64.b64encode(r.content))
    except Exception:
        pass
    return None

