def dns_records(domain):
    """MX/TXT/NS/CNAME：邮件主机与 NS 主机常与源站同机"""
    res = {"A": {}, "AAAA": {}, "CNAME": {}, "MX": [], "NS": [], "TXT": []}
    try:
        import dns.resolver as R
        for t in ("A", "AAAA", "CNAME", "MX", "NS", "TXT"):
            try:
                ans = R.resolve(domain, t, lifetime=5)
            except Exception:
                continue
            for rr in ans:
                v = rr.to_text()
                if t == "MX":
                    res["MX"].append(v)
                elif t == "NS":
                    res["NS"].append(v)
                elif t == "TXT":
                    res["TXT"].append(v)
                elif t == "CNAME":
                    key, _, val = v.partition(" ")
                    res["CNAME"][key] = val
                else:
                    res.setdefault(t, {})[rr.name.to_text()] = v
    except ImportError:
        print("[!] 未安装 dnspython, 跳过 MX/NS/TXT")
    return res

