def ct_subdomains(session, domain):
    names = set()
    for q in (f"%.{domain}", f"{domain}"):
        try:
            r = session.get("https://crt.sh/", params={"q": q, "output": "json"}, timeout=40)
            for row in r.json():
                for n in str(row.get("name_value", "")).splitlines():
                    n = n.strip().lstrip("*.")
                    if n.endswith(domain):
                        names.add(n)
        except Exception as e:
