    public static String d(byte[] enc, int key) {
        byte[] o = enc.clone();
        for (int i = 0; i < o.length; i++) o[i] ^= (byte) (key + (i % 17));
        return new String(o, java.nio.charset.StandardCharsets.UTF_8);
