        case Cat::Proc:       return "process";
        case Cat::Svc:        return "service";
        case Cat::Wmi:        return "wmi";
        case Cat::Net:        return "network";
        case Cat::Wine:       return "wine";
        case Cat::Debugger:   return "debugger";
        case Cat::Artifact:   return "artifact";
        case Cat::Activity:   return "activity";
        case Cat::Hook:       return "hook-integrity";
    }
    return "?";
}

static std::string sfmt(const char* f, ...) {
    char b[1024];
    va_list a; va_start(a, f);
    _vsnprintf_s(b, sizeof b, _TRUNCATE, f, a);
    va_end(a);
    return b;
}

std::string lower(std::string s) {
    for (auto& c : s) c = (char)tolower((unsigned char)c);
    return s;
}
bool contains_ci(const std::string& h, const std::string& n) {
    return lower(h).find(lower(n)) != std::string::npos;
}
std::string W2A(const wchar_t* w) {
    if (!w) return {};
    int n = WideCharToMultiByte(CP_UTF8, 0, w, -1, nullptr, 0, nullptr, nullptr);
    std::string s(n ? n - 1 : 0, 0);
    if (n > 1) WideCharToMultiByte(CP_UTF8, 0, w, -1, s.data(), n, nullptr, nullptr);
    return s;
}
bool file_exists(const wchar_t* p) { return GetFileAttributesW(p) != INVALID_FILE_ATTRIBUTES; }

bool reg_exists(HKEY root, const wchar_t* sub, const wchar_t* val) {
    HKEY k; if (RegOpenKeyExW(root, sub, 0, KEY_READ, &k) != ERROR_SUCCESS) return false;
    bool ok = true;
    if (val) {
        DWORD t, cb = 0;
        ok = RegQueryValueExW(k, val, nullptr, &t, nullptr, &cb) == ERROR_SUCCESS;
 }
    RegCloseKey(k);
    return ok;
}
std::string reg_get(HKEY root, const wchar_t* sub, const wchar_t* val) {
    HKEY k; if (RegOpenKeyExW(root, sub, 0, KEY_READ, &k) != ERROR_SUCCESS) return {};
    DWORD t = 0, cb = 0; std::string out;
    if (RegQueryValueExW(k, val, nullptr, &t, nullptr, &cb) == ERROR_SUCCESS && cb && cb < 0x8000) {
        std::vector<BYTE> b(cb);
        if (RegQueryValueExW(k, val, nullptr, &t, b.data(), &cb) == ERROR_SUCCESS) {
            if (t == REG_SZ) { out = W2A((wchar_t*)b.data()); }
            else if (t == REG_DWORD) { DWORD d; memcpy(&d, b.data(), 4); out = sfmt("0x%08x", d); }
            else if (t == REG_QWORD) { UINT64 q; memcpy(&q, b.data(), 8); out = sfmt("0x%llx", q); }
        }
    }
    RegCloseKey(k);
    return out;
}
std::string env_get(const char* n) { char b[512]; DWORD r = GetEnvironmentVariableA(n, b, sizeof b); return r ? std::string(b, r) : std::string(); }
std::string computer_name() { wchar_t b[256]; DWORD n = 256; if (GetComputerNameW(b, &n)) return W2A(b); return {}; }
std::string user_name() { wchar_t b[256]; DWORD n = 256; if (GetUserNameW(b, &n)) return W2A(b); return {}; }

void* ntdll_get(const char* name) {
    static HMODULE nt = GetModuleHandleW(L"ntdll.dll");
    return nt ? (void*)GetProcAddress(nt, name) : nullptr;
}

