void Engine::add(Cat c, const char* n, int w, std::string d, double conf) {
    std::lock_guard<std::mutex> g(mu_);
    hits_.push_back({ c, n, w, std::move(d), conf });
}
void Engine::group_add(const char* grp, const std::vector<std::string>& hits, int w_each, Cat c) {
    if (hits.empty()) return;
    std::string j; for (size_t i = 0; i < hits.size(); i++) { if (i) j += ", "; j += hits[i]; }
    add(c, grp, (int)(w_each * hits.size()), j, 1.0 / (double)hits.size());
}

